CREATE OR REPLACE FUNCTION get_tree_stats()
RETURNS TABLE(
    total_nullifiers BIGINT,
    tree_height INTEGER,
    next_index BIGINT,
    chain_valid BOOLEAN
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ts.total_nullifiers,
        ts.tree_height,
        ts.next_available_index,
        validate_nullifier_chain()
    FROM tree_state ts
    WHERE tree_id = 'default';
END;
$$ LANGUAGE plpgsql;

