ALTER TABLE tree_state ADD COLUMN IF NOT EXISTS total_loan_payments BIGINT DEFAULT 0;
ALTER TABLE tree_state ADD COLUMN IF NOT EXISTS total_loan_closeouts BIGINT DEFAULT 0;
