COMMIT;
-- Migration: Create USDC withdrawal tracking tables
-- Description: Add tables for tracking USDC withdrawals from smart contract events

BEGIN;

-- Table for tracking USDC withdrawals from smart contract events
CREATE TABLE usdc_withdrawals (
    id SERIAL PRIMARY KEY,
    -- Withdrawal details from smart contract event
    user_address VARCHAR(42) NOT NULL, -- Ethereum address (0x + 40 chars)
    recipient_address VARCHAR(42) NOT NULL, -- Recipient address for withdrawal
    amount NUMERIC(78, 0) NOT NULL, -- U256 amount in USDC (6 decimals)
    withdrawal_amount_usdc NUMERIC(20, 6) GENERATED ALWAYS AS (amount::NUMERIC / 1000000) STORED, -- Human readable USDC amount
    transaction_hash VARCHAR(66) NOT NULL, -- Transaction hash from event
    event_transaction_hash VARCHAR(66) NOT NULL, -- Transaction hash where event was emitted
    
    -- Block and timestamp information
    block_number BIGINT NOT NULL,
    event_timestamp BIGINT NOT NULL, -- Timestamp from contract event
    block_timestamp TIMESTAMP WITH TIME ZONE, -- Actual block timestamp (filled by indexer)
    
    -- Event metadata
    log_index BIGINT NOT NULL,
    event_signature VARCHAR(66) NOT NULL DEFAULT '0x...', -- Event signature for verification
    
    -- Processing status
    status VARCHAR(20) NOT NULL DEFAULT 'pending', -- pending, confirmed, processed, failed
    confirmation_count INTEGER NOT NULL DEFAULT 0,
    required_confirmations INTEGER NOT NULL DEFAULT 12,
    
    -- Database tracking
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    processed_at TIMESTAMP WITH TIME ZONE,
    
    -- Ensure uniqueness of events
    CONSTRAINT unique_withdrawal_event UNIQUE (event_transaction_hash, log_index),
    -- Ensure valid status values
    CONSTRAINT valid_withdrawal_status CHECK (status IN ('pending', 'confirmed', 'processed', 'failed')),
    -- Ensure positive amount
    CONSTRAINT positive_amount CHECK (amount > 0),
    -- Ensure valid confirmation count
    CONSTRAINT valid_confirmations CHECK (confirmation_count >= 0 AND confirmation_count <= required_confirmations + 10)
);

-- Table for tracking user withdrawal balances (aggregated view)
CREATE TABLE user_withdrawal_balances (
    id SERIAL PRIMARY KEY,
    user_address VARCHAR(42) NOT NULL UNIQUE,
    total_withdrawn NUMERIC(78, 0) NOT NULL DEFAULT 0, -- Total USDC withdrawn (in wei)
    total_withdrawn_usdc NUMERIC(20, 6) GENERATED ALWAYS AS (total_withdrawn::NUMERIC / 1000000) STORED, -- Human readable
    withdrawal_count INTEGER NOT NULL DEFAULT 0,
    first_withdrawal_at TIMESTAMP WITH TIME ZONE,
    last_withdrawal_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Ensure positive values
    CONSTRAINT positive_total_withdrawn CHECK (total_withdrawn >= 0),
    CONSTRAINT positive_withdrawal_count CHECK (withdrawal_count >= 0)
);

-- Table for tracking withdrawal processing errors and retry attempts
CREATE TABLE withdrawal_processing_log (
    id SERIAL PRIMARY KEY,
    withdrawal_id INTEGER REFERENCES usdc_withdrawals(id) ON DELETE CASCADE,
    event_type VARCHAR(50) NOT NULL, -- confirmation_check, balance_update, retry, etc.
    status VARCHAR(20) NOT NULL, -- success, error, retry
    message TEXT,
    error_details JSONB,
    retry_count INTEGER NOT NULL DEFAULT 0,
    next_retry_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    -- Ensure valid values
    CONSTRAINT valid_log_status CHECK (status IN ('success', 'error', 'retry', 'skipped'))
);

-- Indexes for efficient querying
CREATE INDEX idx_usdc_withdrawals_user_address ON usdc_withdrawals(user_address);
CREATE INDEX idx_usdc_withdrawals_recipient_address ON usdc_withdrawals(recipient_address);
CREATE INDEX idx_usdc_withdrawals_block_number ON usdc_withdrawals(block_number);
CREATE INDEX idx_usdc_withdrawals_status ON usdc_withdrawals(status);
CREATE INDEX idx_usdc_withdrawals_created_at ON usdc_withdrawals(created_at);
CREATE INDEX idx_usdc_withdrawals_transaction_hash ON usdc_withdrawals(transaction_hash);
CREATE INDEX idx_usdc_withdrawals_event_tx_hash ON usdc_withdrawals(event_transaction_hash);

-- Indexes for user withdrawal balances
CREATE INDEX idx_user_withdrawal_balances_address ON user_withdrawal_balances(user_address);
CREATE INDEX idx_user_withdrawal_balances_total ON user_withdrawal_balances(total_withdrawn);
CREATE INDEX idx_user_withdrawal_balances_last_withdrawal ON user_withdrawal_balances(last_withdrawal_at);

-- Indexes for processing log
CREATE INDEX idx_withdrawal_processing_log_withdrawal_id ON withdrawal_processing_log(withdrawal_id);
CREATE INDEX idx_withdrawal_processing_log_status ON withdrawal_processing_log(status);
CREATE INDEX idx_withdrawal_processing_log_next_retry ON withdrawal_processing_log(next_retry_at) WHERE next_retry_at IS NOT NULL;
CREATE INDEX idx_withdrawal_processing_log_created_at ON withdrawal_processing_log(created_at);

-- Function to update user withdrawal balances when withdrawals are confirmed
CREATE OR REPLACE FUNCTION update_user_withdrawal_balance()
RETURNS TRIGGER AS $$
BEGIN
    -- Only process when status changes to 'confirmed' or 'processed'
    IF NEW.status IN ('confirmed', 'processed') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
        INSERT INTO user_withdrawal_balances (
            user_address, 
            total_withdrawn, 
            withdrawal_count, 
            first_withdrawal_at, 
            last_withdrawal_at,
            updated_at
        ) VALUES (
            NEW.user_address,
            NEW.amount,
            1,
            COALESCE(NEW.block_timestamp, NOW()),
            COALESCE(NEW.block_timestamp, NOW()),
            NOW()
        )
        ON CONFLICT (user_address) DO UPDATE SET
            total_withdrawn = user_withdrawal_balances.total_withdrawn + NEW.amount,
            withdrawal_count = user_withdrawal_balances.withdrawal_count + 1,
            last_withdrawal_at = GREATEST(user_withdrawal_balances.last_withdrawal_at, COALESCE(NEW.block_timestamp, NOW())),
            updated_at = NOW();
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to automatically update user withdrawal balances
CREATE TRIGGER trigger_update_user_withdrawal_balance
    AFTER UPDATE ON usdc_withdrawals
    FOR EACH ROW
    EXECUTE FUNCTION update_user_withdrawal_balance();

-- Triggers to update updated_at columns
CREATE TRIGGER trigger_usdc_withdrawals_updated_at
    BEFORE UPDATE ON usdc_withdrawals
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_user_withdrawal_balances_updated_at
    BEFORE UPDATE ON user_withdrawal_balances
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

COMMIT;-- Migration: Create withdrawal requests table
-- Description: Add table for tracking user-initiated withdrawal requests with KYC validation and balance checks

BEGIN;

-- Table for tracking user withdrawal requests (different from blockchain events)
CREATE TABLE withdrawal_requests (
    id SERIAL PRIMARY KEY,
    -- User identification
    user_id UUID NOT NULL REFERENCES identities(id) ON DELETE CASCADE,
    user_address VARCHAR(42) NOT NULL, -- Ethereum address of the user
    recipient_address VARCHAR(42) NOT NULL, -- Where user wants to withdraw to
    
    -- Withdrawal details
    amount NUMERIC(78, 0) NOT NULL, -- Amount in USDC wei (6 decimals)
    amount_usdc NUMERIC(20, 6) GENERATED ALWAYS AS (amount::NUMERIC / 1000000) STORED, -- Human readable USDC amount
    
    -- Request state tracking
    state VARCHAR(20) NOT NULL DEFAULT 'pending', -- pending, validated, submitted, confirmed, failed, cancelled
    
    -- Validation results
    kyc_validated BOOLEAN NOT NULL DEFAULT FALSE,
    balance_validated BOOLEAN NOT NULL DEFAULT FALSE,
    kyc_status_at_request VARCHAR(20), -- KYC status when request was made
    available_balance_at_request NUMERIC(78, 0), -- Available balance when request was made
    
    -- Smart contract integration
    transaction_hash VARCHAR(66), -- Transaction hash when submitted to contract (null until submitted)
    block_number BIGINT, -- Block number when transaction was mined
    confirmation_count INTEGER NOT NULL DEFAULT 0,
    required_confirmations INTEGER NOT NULL DEFAULT 12,
    
    -- Error tracking
    error_message TEXT, -- Error details if request fails
    validation_errors JSONB, -- Structured validation error details
    
    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    validated_at TIMESTAMP WITH TIME ZONE, -- When KYC and balance validation completed
    submitted_at TIMESTAMP WITH TIME ZONE, -- When submitted to smart contract
    confirmed_at TIMESTAMP WITH TIME ZONE, -- When confirmed on blockchain
    failed_at TIMESTAMP WITH TIME ZONE, -- When request failed
    cancelled_at TIMESTAMP WITH TIME ZONE, -- When user cancelled request
    
    -- Constraints
    CONSTRAINT positive_withdrawal_amount CHECK (amount > 0),
    CONSTRAINT valid_withdrawal_state CHECK (state IN ('pending', 'validated', 'submitted', 'confirmed', 'failed', 'cancelled')),
    CONSTRAINT valid_confirmation_count CHECK (confirmation_count >= 0 AND confirmation_count <= required_confirmations + 10),
    -- Can't have both error and success states
    CONSTRAINT no_error_when_confirmed CHECK (NOT (state = 'confirmed' AND error_message IS NOT NULL))
);

-- Table for tracking withdrawal request processing steps and history
CREATE TABLE withdrawal_request_history (
    id SERIAL PRIMARY KEY,
    withdrawal_request_id INTEGER NOT NULL REFERENCES withdrawal_requests(id) ON DELETE CASCADE,
    
    -- Event details
    event_type VARCHAR(50) NOT NULL, -- kyc_validation, balance_validation, contract_submission, confirmation_check, error, cancellation
    old_state VARCHAR(20), -- Previous state before this event
    new_state VARCHAR(20), -- New state after this event
    
    -- Event results
    success BOOLEAN NOT NULL DEFAULT TRUE,
    message TEXT, -- Human readable message about what happened
    details JSONB, -- Structured event details (validation results, transaction info, etc.)
    
    -- Retry tracking for failed operations
    retry_count INTEGER NOT NULL DEFAULT 0,
    next_retry_at TIMESTAMP WITH TIME ZONE,
    
    -- Timing
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    processing_duration_ms INTEGER, -- How long this step took to process
    
    -- Constraints
    CONSTRAINT valid_event_type CHECK (event_type IN ('kyc_validation', 'balance_validation', 'contract_submission', 'confirmation_check', 'error', 'cancellation', 'retry'))
);

-- Indexes for efficient querying
CREATE INDEX idx_withdrawal_requests_user_id ON withdrawal_requests(user_id);
CREATE INDEX idx_withdrawal_requests_user_address ON withdrawal_requests(user_address);
CREATE INDEX idx_withdrawal_requests_state ON withdrawal_requests(state);
CREATE INDEX idx_withdrawal_requests_created_at ON withdrawal_requests(created_at);
CREATE INDEX idx_withdrawal_requests_transaction_hash ON withdrawal_requests(transaction_hash);
CREATE INDEX idx_withdrawal_requests_pending_validation ON withdrawal_requests(state) WHERE state = 'pending';
CREATE INDEX idx_withdrawal_requests_pending_submission ON withdrawal_requests(state) WHERE state = 'validated';

-- Indexes for history table
CREATE INDEX idx_withdrawal_request_history_request_id ON withdrawal_request_history(withdrawal_request_id);
CREATE INDEX idx_withdrawal_request_history_event_type ON withdrawal_request_history(event_type);
CREATE INDEX idx_withdrawal_request_history_created_at ON withdrawal_request_history(created_at);
CREATE INDEX idx_withdrawal_request_history_next_retry ON withdrawal_request_history(next_retry_at) WHERE next_retry_at IS NOT NULL;

-- Function to automatically update updated_at timestamp
CREATE OR REPLACE FUNCTION update_withdrawal_request_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to update updated_at on changes
CREATE TRIGGER trigger_withdrawal_requests_updated_at
    BEFORE UPDATE ON withdrawal_requests
    FOR EACH ROW
    EXECUTE FUNCTION update_withdrawal_request_updated_at();

-- Function to automatically create history entries for state changes
CREATE OR REPLACE FUNCTION create_withdrawal_request_history()
RETURNS TRIGGER AS $$
BEGIN
    -- Only create history entry if state actually changed
    IF OLD.state IS DISTINCT FROM NEW.state THEN
        INSERT INTO withdrawal_request_history (
            withdrawal_request_id,
            event_type,
            old_state,
            new_state,
            success,
            message,
            details
        ) VALUES (
            NEW.id,
            CASE 
                WHEN NEW.state = 'validated' THEN 'balance_validation'
                WHEN NEW.state = 'submitted' THEN 'contract_submission'
                WHEN NEW.state = 'confirmed' THEN 'confirmation_check'
                WHEN NEW.state = 'failed' THEN 'error'
                WHEN NEW.state = 'cancelled' THEN 'cancellation'
                ELSE 'state_change'
            END,
            OLD.state,
            NEW.state,
            NEW.state NOT IN ('failed', 'cancelled'),
            CASE 
                WHEN NEW.state = 'validated' THEN 'KYC and balance validation completed'
                WHEN NEW.state = 'submitted' THEN 'Withdrawal submitted to smart contract'
                WHEN NEW.state = 'confirmed' THEN 'Withdrawal confirmed on blockchain'
                WHEN NEW.state = 'failed' THEN COALESCE(NEW.error_message, 'Withdrawal failed')
                WHEN NEW.state = 'cancelled' THEN 'Withdrawal cancelled by user'
                ELSE 'State changed to ' || NEW.state
            END,
            jsonb_build_object(
                'old_state', OLD.state,
                'new_state', NEW.state,
                'transaction_hash', NEW.transaction_hash,
                'confirmation_count', NEW.confirmation_count
            )
        );
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to automatically create history entries
CREATE TRIGGER trigger_withdrawal_request_history
    AFTER UPDATE ON withdrawal_requests
    FOR EACH ROW
    EXECUTE FUNCTION create_withdrawal_request_history();

-- Create initial history entry for new requests
CREATE OR REPLACE FUNCTION create_initial_withdrawal_history()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO withdrawal_request_history (
        withdrawal_request_id,
        event_type,
        old_state,
        new_state,
        success,
        message,
        details
    ) VALUES (
        NEW.id,
        'kyc_validation',
        NULL,
        NEW.state,
        TRUE,
        'Withdrawal request created',
        jsonb_build_object(
            'amount_usdc', NEW.amount_usdc,
            'recipient_address', NEW.recipient_address,
            'user_address', NEW.user_address
        )
    );
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to create initial history entry
CREATE TRIGGER trigger_initial_withdrawal_history
    AFTER INSERT ON withdrawal_requests
    FOR EACH ROW
    EXECUTE FUNCTION create_initial_withdrawal_history();

COMMIT;

-- Create investor profiles table for enhanced investor account functionality
-- This migration adds investor-specific profile management and accredited investor tracking

-- ============================================================================
-- INVESTOR PROFILES TABLE
-- ============================================================================

-- Table for investor-specific profile information and regulatory status
CREATE TABLE investor_profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES identities(id) ON DELETE CASCADE UNIQUE,
    accredited_investor BOOLEAN NOT NULL DEFAULT FALSE,
    investment_capacity DECIMAL(20, 6), -- optional maximum investment amount in USDC
    regulatory_jurisdiction VARCHAR(10) NOT NULL DEFAULT 'US', -- e.g., 'US', 'EU', 'UK'
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- INVESTOR PROFILE AUDIT TABLE
-- ============================================================================

-- Audit trail for all investor profile operations
CREATE TABLE investor_profile_audit (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    profile_id UUID NOT NULL REFERENCES investor_profiles(id) ON DELETE CASCADE,
    operation_type VARCHAR(30) NOT NULL CHECK (operation_type IN ('PROFILE_CREATED', 'PROFILE_UPDATED', 'ACCREDITATION_CHANGED', 'CAPACITY_UPDATED', 'JURISDICTION_CHANGED')),
    old_values JSONB,
    new_values JSONB,
    operator_id UUID REFERENCES identities(id),
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- CONSTRAINTS AND VALIDATIONS
-- ============================================================================

-- Investment capacity must be positive if specified
ALTER TABLE investor_profiles ADD CONSTRAINT investor_profiles_positive_capacity 
    CHECK (investment_capacity IS NULL OR investment_capacity > 0);

-- Regulatory jurisdiction must be a valid code
ALTER TABLE investor_profiles ADD CONSTRAINT investor_profiles_valid_jurisdiction
    CHECK (regulatory_jurisdiction ~ '^[A-Z]{2,10}$');

-- Ensure user_id references an investor-type user (application layer will enforce)
-- PostgreSQL doesn't support subqueries in CHECK constraints, so this is handled in application

-- ============================================================================
-- INDEXES FOR PERFORMANCE
-- ============================================================================

-- Primary access patterns
CREATE INDEX idx_investor_profiles_user_id ON investor_profiles(user_id);
CREATE INDEX idx_investor_profiles_accredited ON investor_profiles(accredited_investor);
CREATE INDEX idx_investor_profiles_jurisdiction ON investor_profiles(regulatory_jurisdiction);
CREATE INDEX idx_investor_profiles_created_at ON investor_profiles(created_at);

-- Investment capacity filtering
CREATE INDEX idx_investor_profiles_capacity ON investor_profiles(investment_capacity) WHERE investment_capacity IS NOT NULL;

-- Composite index for accredited investors with capacity
CREATE INDEX idx_investor_profiles_accredited_capacity ON investor_profiles(accredited_investor, investment_capacity) 
    WHERE accredited_investor = true AND investment_capacity IS NOT NULL;

-- Audit table indexes
CREATE INDEX idx_investor_profile_audit_profile_id ON investor_profile_audit(profile_id);
CREATE INDEX idx_investor_profile_audit_operation_type ON investor_profile_audit(operation_type);
CREATE INDEX idx_investor_profile_audit_created_at ON investor_profile_audit(created_at);

-- ============================================================================
-- TRIGGERS FOR AUTOMATIC UPDATES
-- ============================================================================

-- Trigger for updating updated_at timestamp
CREATE TRIGGER update_investor_profiles_updated_at 
    BEFORE UPDATE ON investor_profiles 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

-- Function to create audit records for profile operations
CREATE OR REPLACE FUNCTION create_investor_profile_audit_record()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO investor_profile_audit (profile_id, operation_type, new_values, operator_id)
        VALUES (NEW.id, 'PROFILE_CREATED', to_jsonb(NEW), NEW.user_id);
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        -- Check what changed and create appropriate audit record
        IF OLD.accredited_investor != NEW.accredited_investor THEN
            INSERT INTO investor_profile_audit (profile_id, operation_type, old_values, new_values, operator_id)
            VALUES (NEW.id, 'ACCREDITATION_CHANGED', 
                    jsonb_build_object('accredited_investor', OLD.accredited_investor), 
                    jsonb_build_object('accredited_investor', NEW.accredited_investor), 
                    NEW.user_id);
        ELSIF OLD.investment_capacity != NEW.investment_capacity THEN
            INSERT INTO investor_profile_audit (profile_id, operation_type, old_values, new_values, operator_id)
            VALUES (NEW.id, 'CAPACITY_UPDATED', 
                    jsonb_build_object('investment_capacity', OLD.investment_capacity), 
                    jsonb_build_object('investment_capacity', NEW.investment_capacity), 
                    NEW.user_id);
        ELSIF OLD.regulatory_jurisdiction != NEW.regulatory_jurisdiction THEN
            INSERT INTO investor_profile_audit (profile_id, operation_type, old_values, new_values, operator_id)
            VALUES (NEW.id, 'JURISDICTION_CHANGED', 
                    jsonb_build_object('regulatory_jurisdiction', OLD.regulatory_jurisdiction), 
                    jsonb_build_object('regulatory_jurisdiction', NEW.regulatory_jurisdiction), 
                    NEW.user_id);
        ELSE
            INSERT INTO investor_profile_audit (profile_id, operation_type, old_values, new_values, operator_id)
            VALUES (NEW.id, 'PROFILE_UPDATED', to_jsonb(OLD), to_jsonb(NEW), NEW.user_id);
        END IF;
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Trigger to automatically create audit records
CREATE TRIGGER investor_profile_audit_trigger
    AFTER INSERT OR UPDATE ON investor_profiles
    FOR EACH ROW
    EXECUTE FUNCTION create_investor_profile_audit_record();

