-- Create a new function that accepts either user_id or email for getting investor profile
CREATE OR REPLACE FUNCTION get_investor_profile_by_user_id_or_email(
    profile_user_id UUID DEFAULT NULL,
    lookup_email VARCHAR(255) DEFAULT NULL
)
RETURNS TABLE(
    profile_id UUID,
    user_id UUID,
    user_email VARCHAR(255),
    user_type VARCHAR(20),
    kyc_status VARCHAR(50),
    kyc_submitted_at TIMESTAMP WITH TIME ZONE,
    kyc_verified_at TIMESTAMP WITH TIME ZONE,
    kyc_investor_type kyc_investor_type,
    accredited_investor BOOLEAN,
    investment_capacity DECIMAL(20, 6),
    regulatory_jurisdiction VARCHAR(10),
    profile_created_at TIMESTAMP WITH TIME ZONE,
    profile_updated_at TIMESTAMP WITH TIME ZONE,
    first_name VARCHAR(100),
    last_name VARCHAR(100),
    jurisdiction VARCHAR(10),
    wallet_address VARCHAR(42)
) AS $$
BEGIN
    -- Validate input: exactly one of user_id or email must be provided
    IF (profile_user_id IS NULL AND lookup_email IS NULL) OR (profile_user_id IS NOT NULL AND lookup_email IS NOT NULL) THEN
        RAISE EXCEPTION 'Exactly one of user_id or email must be provided';
    END IF;

    RETURN QUERY
    SELECT 
        ip.id,
        ip.user_id,
        i.email,
        i.user_type,
        i.kyc_status,
        i.kyc_submitted_at,
        i.kyc_verified_at,
        i.kyc_investor_type,
        ip.accredited_investor,
        ip.investment_capacity,
        ip.regulatory_jurisdiction,
        ip.created_at,
        ip.updated_at,
        i.first_name,
        i.last_name,
        i.jurisdiction,
        i.wallet_address
    FROM investor_profiles ip
    INNER JOIN identities i ON ip.user_id = i.id
    WHERE (profile_user_id IS NOT NULL AND i.id = profile_user_id)
       OR (lookup_email IS NOT NULL AND LOWER(i.email) = LOWER(lookup_email));
END;
$$ LANGUAGE plpgsql;-- Migration: Create financial transaction system
-- Description: Add tables for tracking financial transactions separate from state transactions

BEGIN;

-- ============================================================================
-- ACCOUNT FINANCIAL TRANSACTIONS
-- ============================================================================

-- Track all financial deposits/withdrawals to user accounts from smart contract
CREATE TABLE account_financial_transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES identities(id) ON DELETE CASCADE,
    transaction_type VARCHAR(20) NOT NULL, -- DEPOSIT, WITHDRAWAL
    amount DECIMAL(20,6) NOT NULL,
    currency VARCHAR(10) DEFAULT 'USDC',
    transaction_hash VARCHAR(66) NOT NULL, -- Smart contract transaction hash
    blockchain_status VARCHAR(20) DEFAULT 'CONFIRMED', -- PENDING, CONFIRMED, FAILED
    block_number BIGINT,
    processed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    CONSTRAINT valid_account_transaction_type CHECK (
        transaction_type IN ('DEPOSIT', 'WITHDRAWAL')
    ),
    CONSTRAINT positive_amount CHECK (amount > 0),
    UNIQUE(transaction_hash)
);

-- ============================================================================
-- CREDIT LINE FINANCIAL TRANSACTIONS
-- ============================================================================

-- Track financial movements in/out of credit lines
CREATE TABLE credit_line_financial_transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    credit_line_id UUID NOT NULL REFERENCES credit_lines(id) ON DELETE CASCADE,
    merchant_id UUID NOT NULL REFERENCES merchants(id) ON DELETE CASCADE,
    transaction_type VARCHAR(20) NOT NULL, -- DRAW, PAYMENT, INTEREST, FEE
    amount DECIMAL(20,6) NOT NULL,
    currency VARCHAR(10) DEFAULT 'USDC',
    -- Link to state transaction if applicable
    state_transaction_id UUID, -- Can reference state_transactions(id) if this was triggered by a state change
    transaction_hash VARCHAR(66), -- Blockchain transaction hash if applicable
    description TEXT,
    processed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    CONSTRAINT valid_credit_line_transaction_type CHECK (
        transaction_type IN ('DRAW', 'PAYMENT', 'INTEREST', 'FEE', 'PENALTY')
    ),
    CONSTRAINT positive_amount CHECK (amount > 0)
);

-- ============================================================================
-- INDEXES FOR PERFORMANCE
-- ============================================================================

-- Account financial transactions indexes
CREATE INDEX idx_account_financial_transactions_user_id ON account_financial_transactions(user_id);
CREATE INDEX idx_account_financial_transactions_type ON account_financial_transactions(transaction_type);
CREATE INDEX idx_account_financial_transactions_hash ON account_financial_transactions(transaction_hash);
CREATE INDEX idx_account_financial_transactions_processed_at ON account_financial_transactions(processed_at DESC);

-- Credit line financial transactions indexes
CREATE INDEX idx_credit_line_financial_transactions_credit_line_id ON credit_line_financial_transactions(credit_line_id);
CREATE INDEX idx_credit_line_financial_transactions_merchant_id ON credit_line_financial_transactions(merchant_id);
CREATE INDEX idx_credit_line_financial_transactions_type ON credit_line_financial_transactions(transaction_type);
CREATE INDEX idx_credit_line_financial_transactions_processed_at ON credit_line_financial_transactions(processed_at DESC);

-- ============================================================================
-- UPDATE EXISTING TABLES
-- ============================================================================

-- Add financial transaction tracking to user_balances
ALTER TABLE user_balances
ADD COLUMN IF NOT EXISTS last_financial_transaction_at TIMESTAMP WITH TIME ZONE;

-- Add financial transaction tracking to credit_lines
ALTER TABLE credit_lines
ADD COLUMN IF NOT EXISTS total_financial_volume DECIMAL(20,6) DEFAULT 0,
ADD COLUMN IF NOT EXISTS last_financial_transaction_at TIMESTAMP WITH TIME ZONE;

-- ============================================================================
-- UNIFIED FINANCIAL TRANSACTION VIEW
-- ============================================================================

-- Combined view of all financial transactions for a user
CREATE VIEW user_financial_transactions AS
SELECT
    'ACCOUNT'::text as transaction_category,
    aft.id,
    aft.user_id,
    aft.transaction_type,
    aft.amount,
    aft.currency,
    aft.transaction_hash,
    aft.processed_at,
    NULL::uuid as credit_line_id,
    ('Smart contract ' || LOWER(aft.transaction_type))::text as description
FROM account_financial_transactions aft

UNION ALL

SELECT
    'CREDIT_LINE'::text as transaction_category,
    clft.id,
    clft.merchant_id as user_id,
    clft.transaction_type,
    clft.amount,
    clft.currency,
    clft.transaction_hash,
    clft.processed_at,
    clft.credit_line_id,
    COALESCE(clft.description, 'Credit line ' || LOWER(clft.transaction_type))::text as description
FROM credit_line_financial_transactions clft;

-- ============================================================================
-- TRIGGERS FOR UPDATED_AT TIMESTAMPS
-- ============================================================================

-- Function to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Triggers for financial transaction tables
CREATE TRIGGER update_account_financial_transactions_updated_at
    BEFORE UPDATE ON account_financial_transactions
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_credit_line_financial_transactions_updated_at
    BEFORE UPDATE ON credit_line_financial_transactions
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ============================================================================
-- HELPER FUNCTIONS
-- ============================================================================

-- Function to get user's financial transaction summary
CREATE OR REPLACE FUNCTION get_user_financial_summary(p_user_id UUID)
RETURNS TABLE(
    total_deposits DECIMAL(20,6),
    total_withdrawals DECIMAL(20,6),
    net_account_flow DECIMAL(20,6),
    total_credit_line_payments DECIMAL(20,6),
    total_credit_line_draws DECIMAL(20,6)
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        COALESCE(SUM(CASE WHEN aft.transaction_type = 'DEPOSIT' THEN aft.amount ELSE 0 END), 0) as total_deposits,
        COALESCE(SUM(CASE WHEN aft.transaction_type = 'WITHDRAWAL' THEN aft.amount ELSE 0 END), 0) as total_withdrawals,
        COALESCE(SUM(CASE WHEN aft.transaction_type = 'DEPOSIT' THEN aft.amount
                         WHEN aft.transaction_type = 'WITHDRAWAL' THEN -aft.amount ELSE 0 END), 0) as net_account_flow,
        COALESCE(SUM(CASE WHEN clft.transaction_type = 'PAYMENT' THEN clft.amount ELSE 0 END), 0) as total_credit_line_payments,
        COALESCE(SUM(CASE WHEN clft.transaction_type = 'DRAW' THEN clft.amount ELSE 0 END), 0) as total_credit_line_draws
    FROM identities i
    LEFT JOIN account_financial_transactions aft ON aft.user_id = i.id
    LEFT JOIN merchants m ON m.user_id = i.id
    LEFT JOIN credit_line_financial_transactions clft ON clft.merchant_id = m.id
    WHERE i.id = p_user_id;
END;
$$ LANGUAGE plpgsql;

COMMIT;

-- ============================================================================
-- MIGRATION NOTES
-- ============================================================================

-- This migration creates the financial transaction system with:
-- 1. account_financial_transactions - Track smart contract deposits/withdrawals
-- 2. credit_line_financial_transactions - Track credit line draws/payments
-- 3. user_financial_transactions view - Unified view of all financial activity
-- 4. Helper functions for financial summaries
-- 5. Indexes for performance
-- 6. Triggers for automatic timestamp updates
-- Fix withdrawal state constraint to include 'approved' state
-- This addresses the constraint violation when approving withdrawals

-- Drop the existing constraint
ALTER TABLE withdrawal_requests DROP CONSTRAINT valid_withdrawal_state;

-- Add the updated constraint that includes 'approved'
ALTER TABLE withdrawal_requests ADD CONSTRAINT valid_withdrawal_state
CHECK (state IN ('pending', 'approved', 'validated', 'submitted', 'confirmed', 'failed', 'cancelled'));-- Fix withdrawal request history constraint to include 'approval' and 'state_change' event types
-- This addresses the constraint violation when approving withdrawals

-- Drop the existing constraint
ALTER TABLE withdrawal_request_history DROP CONSTRAINT valid_event_type;

-- Add the updated constraint that includes 'approval' and 'state_change'
ALTER TABLE withdrawal_request_history ADD CONSTRAINT valid_event_type
CHECK (event_type IN ('kyc_validation', 'balance_validation', 'contract_submission', 'confirmation_check', 'error', 'cancellation', 'retry', 'approval', 'state_change'));

-- Update the trigger function to handle 'approved' state properly
CREATE OR REPLACE FUNCTION create_withdrawal_request_history()
RETURNS TRIGGER AS $$
BEGIN
    -- Only create history entry if state actually changed
    IF OLD.state IS DISTINCT FROM NEW.state THEN
        INSERT INTO withdrawal_request_history (
            withdrawal_request_id,
            event_type,
            old_state,
            new_state,
            success,
            message,
            details
        ) VALUES (
            NEW.id,
            CASE
                WHEN NEW.state = 'approved' THEN 'approval'
                WHEN NEW.state = 'validated' THEN 'balance_validation'
                WHEN NEW.state = 'submitted' THEN 'contract_submission'
                WHEN NEW.state = 'confirmed' THEN 'confirmation_check'
                WHEN NEW.state = 'failed' THEN 'error'
                WHEN NEW.state = 'cancelled' THEN 'cancellation'
                ELSE 'state_change'
            END,
            OLD.state,
            NEW.state,
            NEW.state NOT IN ('failed', 'cancelled'),
            CASE
                WHEN NEW.state = 'approved' THEN 'Withdrawal approved by admin'
                WHEN NEW.state = 'validated' THEN 'KYC and balance validation completed'
                WHEN NEW.state = 'submitted' THEN 'Withdrawal submitted to smart contract'
                WHEN NEW.state = 'confirmed' THEN 'Withdrawal confirmed on blockchain'
                WHEN NEW.state = 'failed' THEN COALESCE(NEW.error_message, 'Withdrawal failed')
                WHEN NEW.state = 'cancelled' THEN 'Withdrawal cancelled by user'
                ELSE 'State changed to ' || NEW.state
            END,
            jsonb_build_object(
                'old_state', OLD.state,
                'new_state', NEW.state,
                'transaction_hash', NEW.transaction_hash,
                'confirmation_count', NEW.confirmation_count
            )
        );
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;-- Company-Based Document Storage Infrastructure
-- This migration adds company-based document storage with role-based access controls
-- and ZK proof integration for the Arda Credit ecosystem

-- ============================================================================
-- COMPANY MANAGEMENT TABLES
-- ============================================================================

-- Table for company/organization management
CREATE TABLE companies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(255) NOT NULL,
    company_type VARCHAR(20) NOT NULL CHECK (company_type IN ('originator', 'investor')),
    kyb_status VARCHAR(20) NOT NULL DEFAULT 'not_submitted' CHECK (kyb_status IN ('not_submitted', 'pending', 'approved', 'rejected')),
    kyb_submitted_at TIMESTAMP WITH TIME ZONE,
    kyb_verified_at TIMESTAMP WITH TIME ZONE,
    
    -- Company contact and legal information
    legal_name VARCHAR(500),
    tax_id VARCHAR(50),
    registration_number VARCHAR(100),
    jurisdiction VARCHAR(100),
    address_line1 VARCHAR(255),
    address_line2 VARCHAR(255),
    city VARCHAR(100),
    state_province VARCHAR(100),
    postal_code VARCHAR(20),
    country VARCHAR(100),
    
    -- Document storage configuration
    s3_bucket_prefix VARCHAR(100), -- Company-specific S3 bucket prefix
    encryption_key_id VARCHAR(255), -- AWS KMS key ID for company-specific encryption
    document_retention_days INTEGER DEFAULT 2555, -- ~7 years default retention
    
    -- Audit and compliance
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID REFERENCES identities(id),
    
    UNIQUE(name, company_type) -- Prevent duplicate company names within same type
);

-- Table for team member roles within companies
CREATE TABLE team_members (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES identities(id) ON DELETE CASCADE,
    role VARCHAR(20) NOT NULL CHECK (role IN ('admin', 'write', 'read')),
    
    -- Role-specific permissions
    can_upload_documents BOOLEAN DEFAULT FALSE,
    can_download_documents BOOLEAN DEFAULT TRUE,
    can_delete_documents BOOLEAN DEFAULT FALSE,
    can_approve_documents BOOLEAN DEFAULT FALSE,
    can_manage_team BOOLEAN DEFAULT FALSE,
    can_view_audit_logs BOOLEAN DEFAULT FALSE,
    
    -- Status and lifecycle
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'suspended')),
    invited_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    joined_at TIMESTAMP WITH TIME ZONE,
    last_active_at TIMESTAMP WITH TIME ZONE,
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID REFERENCES identities(id),
    
    UNIQUE(company_id, user_id) -- One role per user per company
);

-- ============================================================================
-- DOCUMENT STORAGE TABLES
-- ============================================================================

-- Table for document metadata and access control
CREATE TABLE documents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    
    -- Document identification
    filename VARCHAR(500) NOT NULL,
    original_filename VARCHAR(500) NOT NULL,
    file_extension VARCHAR(10) NOT NULL,
    mime_type VARCHAR(100) NOT NULL,
    file_size_bytes BIGINT NOT NULL CHECK (file_size_bytes > 0),
    
    -- Document categorization
    document_type VARCHAR(50) NOT NULL CHECK (document_type IN ('loan_contract', 'financial_statement', 'kyc_document', 'legal_document', 'other')),
    deal_id UUID, -- Optional reference to specific deal
    category VARCHAR(100), -- Additional categorization
    tags TEXT[], -- Array of tags for searchability
    
    -- Storage and security
    s3_bucket VARCHAR(100) NOT NULL,
    s3_key VARCHAR(500) NOT NULL,
    s3_version_id VARCHAR(100), -- S3 object version for immutability
    
    -- Document integrity and verification
    sha256_hash VARCHAR(64) NOT NULL, -- SHA-256 hash for integrity verification
    document_fingerprint VARCHAR(128), -- Additional fingerprint for duplicate detection
    encryption_status VARCHAR(20) DEFAULT 'encrypted' CHECK (encryption_status IN ('encrypted', 'unencrypted')),
    
    -- Access control and workflow
    access_level VARCHAR(20) NOT NULL DEFAULT 'company' CHECK (access_level IN ('public', 'company', 'deal', 'restricted')),
    approval_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('pending', 'approved', 'rejected')),
    approved_by UUID REFERENCES identities(id),
    approved_at TIMESTAMP WITH TIME ZONE,
    
    -- Document lifecycle
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived', 'deleted')),
    expires_at TIMESTAMP WITH TIME ZONE, -- Optional expiration date
    archived_at TIMESTAMP WITH TIME ZONE,
    deleted_at TIMESTAMP WITH TIME ZONE,
    
    -- Metadata and versioning
    version INTEGER DEFAULT 1,
    parent_document_id UUID REFERENCES documents(id), -- For document revisions
    metadata JSONB, -- Additional document metadata
    
    -- Audit trail
    uploaded_by UUID NOT NULL REFERENCES identities(id),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    UNIQUE(s3_bucket, s3_key), -- Ensure unique S3 storage location
    UNIQUE(sha256_hash, company_id) -- Prevent duplicate documents within company
);

-- Table for document access audit logs
CREATE TABLE document_audit_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES identities(id),
    
    -- Audit event details
    action VARCHAR(50) NOT NULL CHECK (action IN ('upload', 'download', 'view', 'delete', 'approve', 'reject', 'share', 'update_metadata')),
    result VARCHAR(20) NOT NULL CHECK (result IN ('success', 'failure', 'denied')),
    
    -- Request context
    ip_address INET,
    user_agent TEXT,
    request_id VARCHAR(100), -- For correlating with application logs
    
    -- Additional context
    details JSONB, -- Additional audit details (file size, permissions checked, etc.)
    error_message TEXT, -- If result = 'failure' or 'denied'
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table for document sharing and temporary access
CREATE TABLE document_shares (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    
    -- Sharing configuration
    share_token VARCHAR(128) NOT NULL UNIQUE, -- Secure random token for access
    share_type VARCHAR(20) NOT NULL CHECK (share_type IN ('download', 'view', 'temporary')),
    
    -- Access control
    allowed_downloads INTEGER DEFAULT 1, -- Number of allowed downloads
    downloads_used INTEGER DEFAULT 0,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    
    -- Sharing context
    shared_by UUID NOT NULL REFERENCES identities(id),
    shared_with_email VARCHAR(255), -- Optional: specific email restriction
    access_restrictions JSONB, -- Additional access restrictions
    
    -- Status
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'expired', 'revoked')),
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_by UUID REFERENCES identities(id),
    
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- ZK PROOF INTEGRATION TABLES
-- ============================================================================

-- Table for document state transitions in ZK proofs
CREATE TABLE document_state_transitions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    
    -- ZK proof integration
    transaction_hash BYTEA NOT NULL, -- Hash for zkVM compatibility
    state_transition_type VARCHAR(50) NOT NULL CHECK (state_transition_type IN ('document_upload', 'document_approval', 'document_deletion', 'access_grant', 'access_revoke')),
    
    -- State data
    previous_state_hash BYTEA,
    new_state_hash BYTEA NOT NULL,
    merkle_proof BYTEA, -- Merkle proof for state inclusion
    
    -- Batch processing integration
    included_in_batch_id INTEGER REFERENCES proof_batches(id),
    batch_position INTEGER, -- Position within the batch
    
    -- Metadata
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL REFERENCES identities(id)
);

