SELECT
    ae.event_id,
    ae.loan_id as deal_id,  -- Keep the field name for backward compatibility
    ae.user_id,
    ae.loan_operation_type,
    ae.operation_amount,
    ae.nullifier_value,
    ae."timestamp",
    ae.batch_id,
    ae.transaction_hash,
    ae.root_before,
